#!/usr/bin/env node
// Writes protocol/vectors.json.
//
// The client implements this protocol a second time, in VB, on a platform with
// no easy way to inspect a byte stream. The only thing that makes that safe is a
// list of concrete bytes to compare against -- produced from the same code the
// server runs, checked in, and regenerated by `npm test` so a change to the wire
// format cannot be silent.
//
// The vectors themselves are in protocol/vectors.js, because test/vectors.test.js
// needs to build the same object and compare. This file only writes it down.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildVectors } from '../protocol/vectors.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const outputPath = path.join(here, '..', 'protocol', 'vectors.json');

const vectors = buildVectors();
fs.writeFileSync(outputPath, `${JSON.stringify(vectors, null, 2)}\n`);
console.log(
  `wrote ${path.relative(process.cwd(), outputPath)}: `
  + `${vectors.payloads.length} payload(s), ${vectors.frames.length} sealed frame(s).`,
);
